// MEGATOOL FB Campaign Reader
// Ports apps_script getFullFBCampaignData + token retry logic to n8n.
// Tokens are hardcoded below — replace the PASTE_TOKEN_HERE placeholders
// with real Facebook Graph access tokens (long EAA... strings).

const FB_ACCESS_TOKENS = [
  'PASTE_TOKEN_1_HERE',
  'PASTE_TOKEN_2_HERE'
];

const FB_API_VERSION = 'v26.0';
const FB_API_BASE = `https://graph.facebook.com/${FB_API_VERSION}`;

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function fbFetch(url) {
  // Exponential backoff for rate-limit / quota errors.
  const maxAttempts = 4;
  let lastErr = null;
  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    try {
      const res = await this.helpers.httpRequest({
        method: 'GET',
        url,
        json: true,
        returnFullResponse: true,
        timeout: 60000,
        ignoreHttpStatusErrors: true,
      });
      const body = res.body || {};
      const err = body && body.error;
      if (err) {
        const code = err.code;
        const sub = err.error_subcode;
        const msg = String(err.message || '');
        const isRate =
          code === 4 || code === 17 || code === 32 || code === 613 ||
          sub === 2446079 ||
          /rate limit|too many calls|user request limit/i.test(msg);
        if (isRate && attempt < maxAttempts) {
          const wait = 5000 * Math.pow(2, attempt - 1);
          await sleep(wait);
          continue;
        }
      }
      return body;
    } catch (e) {
      lastErr = e;
      if (attempt < maxAttempts) {
        await sleep(5000 * Math.pow(2, attempt - 1));
        continue;
      }
      throw e;
    }
  }
  if (lastErr) throw lastErr;
  return null;
}

const fetchFb = fbFetch.bind(this);

// Probe a token against the campaign. Returns { ok, err } — err carries the
// raw Graph error so the caller can report WHY a token failed instead of
// collapsing every cause into one opaque "no token could read it".
async function probeToken(campaignId, token) {
  const url = `${FB_API_BASE}/${encodeURIComponent(campaignId)}?fields=id&access_token=${encodeURIComponent(token)}`;
  try {
    const body = await fetchFb(url);
    if (body && body.error) {
      const e = body.error;
      return { ok: false, err: { code: e.code, subcode: e.error_subcode, type: e.type, message: e.message } };
    }
    if (body && body.id) return { ok: true };
    return { ok: false, err: { message: 'Empty response from Graph API (no id, no error)' } };
  } catch (e) {
    return { ok: false, err: { message: 'Request failed: ' + (e && e.message ? e.message : String(e)) } };
  }
}

// Is the token itself alive, independent of this campaign? Separates "token is
// dead/expired" from "token is fine but cannot see this ad account".
async function checkTokenAlive(token) {
  try {
    const body = await fetchFb(`${FB_API_BASE}/me?fields=id,name&access_token=${encodeURIComponent(token)}`);
    if (body && body.error) {
      const e = body.error;
      return { alive: false, reason: `code ${e.code}${e.error_subcode ? '/' + e.error_subcode : ''}: ${e.message}` };
    }
    return { alive: true, id: body && body.id, name: body && body.name };
  } catch (e) {
    return { alive: false, reason: (e && e.message) || String(e) };
  }
}

async function getCreativeDetails(creativeId, token) {
  const fields = 'id,name,object_story_spec,asset_feed_spec,url_tags,effective_object_story_id,thumbnail_url,image_url,body,title,call_to_action_type,link_url';
  // thumbnail_width/height force a usable preview. FB's default thumbnail_url is
  // a 64x64 q75 crop, which is all the image we get for creatives that carry no
  // image_url (see hydrateFromPost) — stretched into a card it looks broken.
  const url = `${FB_API_BASE}/${encodeURIComponent(creativeId)}?fields=${encodeURIComponent(fields)}&thumbnail_width=1080&thumbnail_height=1080&access_token=${encodeURIComponent(token)}`;
  try {
    const body = await fetchFb(url);
    if (body && body.error) return { id: creativeId, error: body.error.message || 'creative error' };
    return body;
  } catch (e) {
    return { id: creativeId, error: e.message };
  }
}

// Placement-customized / Advantage+ creatives (object_type SHARE, no link_data)
// keep every text asset in parallel arrays under asset_feed_spec instead of
// object_story_spec. It is all readable with plain ads_read — no Page access
// involved — so this runs before hydrateFromPost and costs no extra request.
// Where a campaign varies copy per placement the arrays hold several entries
// and asset_customization_rules map them to placements; we take the first,
// which is what FB treats as the default and renders in the ad preview.
function hydrateFromAssetFeedSpec(creative) {
  const spec = creative.asset_feed_spec;
  if (!spec) return;
  const first = (arr) => (Array.isArray(arr) && arr.length > 0 ? arr[0] : null);

  const title = first(spec.titles);
  const body = first(spec.bodies);
  const linkAsset = first(spec.link_urls);
  const cta = first(spec.call_to_action_types);

  // FB stores titles with the operator's trailing whitespace intact but strips
  // it on the top-level `title` field — match that so cards render alike.
  if (!creative.title && title && title.text) creative.title = String(title.text).trim();
  if (!creative.body && body && body.text) creative.body = body.text;
  if (!creative.link_url && linkAsset && linkAsset.website_url) creative.link_url = linkAsset.website_url;
  if (!creative.call_to_action_type && cta) creative.call_to_action_type = cta;
}

// Ads built from an existing Page post carry nothing on the creative itself:
// object_story_spec is just { page_id, instagram_user_id } and the copy, link,
// CTA and full-size image all live on the post. Dereference
// effective_object_story_id and fold the post's data back into the SAME creative
// fields a normal link_data creative would have populated, so every consumer
// (tracking-URL extraction, NB asset upload, the UI cards) works unchanged.
// Fails soft — reading a post needs page-level scope an ads-only token may lack,
// and a missing link is better than a failed campaign read.
async function hydrateFromPost(creative, token) {
  const storyId = creative.effective_object_story_id;
  const spec = creative.object_story_spec || {};
  // creative.link_url covers the asset_feed_spec case already resolved above —
  // without it we'd burn a doomed request and stamp a misleading post_error.
  if (!storyId || creative.link_url || spec.link_data || spec.video_data) return;

  const fields = 'message,full_picture,call_to_action{type,value{link}},attachments{title,description,unshimmed_url,target{url},media{image{src}}}';
  const url = `${FB_API_BASE}/${encodeURIComponent(storyId)}?fields=${encodeURIComponent(fields)}&access_token=${encodeURIComponent(token)}`;

  // Failures are reported on the creative itself, not via console.log — this
  // workflow runs as a production webhook, where Code-node logs go to the n8n
  // server log and are not reachable from the UI. post_error rides along in the
  // response so the operator can read it straight off "Copy raw JSON".
  let post;
  try {
    post = await fetchFb(url);
  } catch (e) {
    creative.post_error = { stage: 'request', message: (e && e.message) || String(e) };
    return;
  }
  if (!post || post.error) {
    creative.post_error = (post && post.error) || { message: 'empty response' };
    return;
  }

  const att = (post.attachments && Array.isArray(post.attachments.data) && post.attachments.data[0]) || {};
  const cta = post.call_to_action || {};
  // target.url / unshimmed_url are the real destination; attachments.url is FB's
  // l.facebook.com redirect wrapper, which Binom would not recognise as the offer.
  const link = (att.target && att.target.url) || att.unshimmed_url || (cta.value && cta.value.link) || '';
  const image = post.full_picture || (att.media && att.media.image && att.media.image.src) || '';

  if (!creative.link_url && link) creative.link_url = link;
  if (!creative.title && att.title) creative.title = att.title;
  if (!creative.body && (post.message || att.description)) creative.body = post.message || att.description;
  if (!creative.call_to_action_type && cta.type) creative.call_to_action_type = cta.type;
  if (!creative.image_url && image) creative.image_url = image;

  if (!link) {
    creative.post_error = {
      stage: 'parse',
      message: 'post read OK but no link found',
      attachmentKeys: Object.keys(att),
      postKeys: Object.keys(post),
    };
  }
}

// Resolve a FB video_id → playable .mp4 URL via /VIDEO_ID?fields=source. The
// URL is short-lived and only valid for a few minutes, but that's enough time
// for downstream n8n nodes to download it. Returns null on any error so the
// caller can fall back to the thumbnail.
async function getVideoSource(videoId, token) {
  // Query the current API version's format array (renditions) plus the legacy
  // v18.0 source field (last version to return progressive mp4 by default).
  // Prefer any URL that lacks the DASH marker; fall back to source last.
  const tokenQ = `access_token=${encodeURIComponent(token)}`;
  const currentBase = `${FB_API_BASE}/${encodeURIComponent(videoId)}`;
  const v18Base = `https://graph.facebook.com/v18.0/${encodeURIComponent(videoId)}`;
  try {
    const [fmtBody, srcBody, v18Body] = await Promise.all([
      fetchFb(`${currentBase}?fields=format&${tokenQ}`).catch(() => null),
      fetchFb(`${currentBase}?fields=source&${tokenQ}`).catch(() => null),
      fetchFb(`${v18Base}?fields=source&${tokenQ}`).catch(() => null),
    ]);
    console.log('[getVideoSource] videoId=' + videoId);
    console.log('[getVideoSource] format count=' + ((fmtBody && fmtBody.format && fmtBody.format.length) || 0));
    if (fmtBody && Array.isArray(fmtBody.format)) {
      fmtBody.format.forEach((r, i) => console.log('  format[' + i + '] filter=' + r.filter + ' w=' + r.width + ' h=' + r.height + ' isDash=' + /dash_/i.test(String(r.url || ''))));
    }
    console.log('[getVideoSource] v21 source isDash=' + (srcBody && srcBody.source ? /dash_/i.test(srcBody.source) : 'no-source'));
    console.log('[getVideoSource] v18 source isDash=' + (v18Body && v18Body.source ? /dash_/i.test(v18Body.source) : 'no-source'));

    const renditions = (fmtBody && Array.isArray(fmtBody.format)) ? fmtBody.format : [];
    const progressive = renditions
      .filter(r => r && r.url && !/dash_/i.test(String(r.url)))
      .sort((a, b) => (Number(b.width) || 0) - (Number(a.width) || 0));
    if (progressive.length > 0) { console.log('[getVideoSource] picked format progressive: ' + progressive[0].url.substring(0, 100)); return String(progressive[0].url); }

    if (v18Body && !v18Body.error && v18Body.source && !/dash_/i.test(v18Body.source)) {
      console.log('[getVideoSource] picked v18 source: ' + v18Body.source.substring(0, 100));
      return String(v18Body.source);
    }
    if (srcBody && !srcBody.error && srcBody.source) {
      console.log('[getVideoSource] fell back to v21 source (DASH): ' + srcBody.source.substring(0, 100));
      return String(srcBody.source);
    }
    return null;
  } catch (e) {
    console.log('[getVideoSource] error: ' + (e && e.message));
    return null;
  }
}

async function getFullCampaign(campaignId, token) {
  // Campaign
  const campaignFields = 'id,name,objective,status,effective_status,daily_budget,lifetime_budget,bid_strategy,special_ad_categories,account_id';
  const campaignUrl = `${FB_API_BASE}/${encodeURIComponent(campaignId)}?fields=${encodeURIComponent(campaignFields)}&access_token=${encodeURIComponent(token)}`;
  const campaign = await fetchFb(campaignUrl);
  if (!campaign || campaign.error) {
    return { error: (campaign && campaign.error && campaign.error.message) || 'Failed to fetch campaign' };
  }

  // Adsets (paginated) — filter to ACTIVE at the Graph API so FB never returns
  // paused/archived rows and we don't burn tokens on creative fetches we'd
  // throw away client-side.
  const adsetFields = 'id,name,status,effective_status,daily_budget,lifetime_budget,bid_strategy,bid_amount,billing_event,optimization_goal,targeting,promoted_object,start_time,end_time';
  const ACTIVE_FILTER = encodeURIComponent('["ACTIVE"]');
  let adsets = [];
  let adsetsUrl = `${FB_API_BASE}/${encodeURIComponent(campaignId)}/adsets?fields=${encodeURIComponent(adsetFields)}&effective_status=${ACTIVE_FILTER}&limit=100&access_token=${encodeURIComponent(token)}`;
  while (adsetsUrl) {
    const page = await fetchFb(adsetsUrl);
    if (!page || page.error) {
      return { error: (page && page.error && page.error.message) || 'Failed to fetch adsets' };
    }
    if (Array.isArray(page.data)) adsets = adsets.concat(page.data);
    adsetsUrl = (page.paging && page.paging.next) || null;
    if (adsetsUrl) await sleep(300);
  }

  // Ads per adset (paginated) + creative details per ad. Video sources are
  // resolved lazily and cached per execution — many ads in one campaign tend
  // to share the same video_id (and even when they don't, the cache is free).
  const adFields = 'id,name,status,effective_status,creative';
  const videoSourceCache = {};
  let totalAds = 0;
  for (const adset of adsets) {
    adset.ads = [];
    let adsUrl = `${FB_API_BASE}/${encodeURIComponent(adset.id)}/ads?fields=${encodeURIComponent(adFields)}&effective_status=${ACTIVE_FILTER}&limit=100&access_token=${encodeURIComponent(token)}`;
    while (adsUrl) {
      const page = await fetchFb(adsUrl);
      if (!page || page.error) {
        // Skip this adset's ads on error but continue
        break;
      }
      if (Array.isArray(page.data)) {
        for (const ad of page.data) {
          if (ad.creative && ad.creative.id) {
            const creative = await getCreativeDetails(ad.creative.id, token);
            if (creative && !creative.error) {
              const videoId = creative.object_story_spec && creative.object_story_spec.video_data && creative.object_story_spec.video_data.video_id;
              if (videoId) {
                if (!(videoId in videoSourceCache)) {
                  await sleep(150);
                  videoSourceCache[videoId] = await getVideoSource(videoId, token);
                }
                if (videoSourceCache[videoId]) {
                  creative.video_source_url = videoSourceCache[videoId];
                }
              }
              hydrateFromAssetFeedSpec(creative);
              await hydrateFromPost(creative, token);
              ad.creative = creative;
            }
            await sleep(200);
          }
          adset.ads.push(ad);
        }
      }
      adsUrl = (page.paging && page.paging.next) || null;
      if (adsUrl) await sleep(300);
    }
    totalAds += adset.ads.length;
    await sleep(300);
  }

  return { campaign, adsets, totalAds };
}

// ── main ──
const input = $input.first().json || {};
const campaignId = String(
  (input.body && input.body.campaignId) ||
  input.campaignId ||
  ''
).trim();

if (!campaignId) {
  return [{ json: { ok: false, error: 'Missing campaignId in request body' } }];
}

const tokens = FB_ACCESS_TOKENS.map((t) => String(t || '').trim()).filter((t) => t.length > 0 && t !== 'PASTE_TOKEN_1_HERE' && t !== 'PASTE_TOKEN_2_HERE' && !/^PASTE_TOKEN_\d+_HERE$/.test(t));
if (tokens.length === 0) {
  return [{ json: { ok: false, error: 'No FB access tokens configured — edit the workflow and replace PASTE_TOKEN_*_HERE placeholders with real tokens' } }];
}

// Find working token via cheap probe, keeping each failure reason.
let workingToken = null;
let workingIndex = -1;
const probeFailures = [];
for (let i = 0; i < tokens.length; i++) {
  const res = await probeToken(campaignId, tokens[i]);
  if (res.ok) {
    workingToken = tokens[i];
    workingIndex = i;
    break;
  }
  probeFailures.push({ tokenIndex: i, tokenTail: tokens[i].slice(-6), ...res.err });
  console.log('[probe] token#' + i + ' (...' + tokens[i].slice(-6) + ') failed: ' + JSON.stringify(res.err));
  await sleep(300);
}

if (!workingToken) {
  // Every token failed. Check whether the tokens are dead vs merely blind to
  // this campaign, and translate the Graph codes into a human hint.
  const liveness = [];
  for (let i = 0; i < tokens.length; i++) {
    const alive = await checkTokenAlive(tokens[i]);
    liveness.push({ tokenIndex: i, tokenTail: tokens[i].slice(-6), ...alive });
    await sleep(200);
  }

  const codes = probeFailures.map((f) => f.code);
  let hint;
  if (liveness.some((l) => !l.alive)) {
    hint = 'At least one token is expired or invalid — regenerate it (Graph error on /me).';
  } else if (codes.includes(190)) {
    hint = 'Token expired or was invalidated (code 190) — regenerate it.';
  } else if (codes.includes(200) || codes.includes(10) || codes.includes(299)) {
    hint = 'Token is alive but lacks ads_read/ads_management permission for this ad account (code 200/10/299). Grant the scope, or the app needs Advanced Access for ad accounts it does not own.';
  } else if (codes.includes(4) || codes.includes(17) || codes.includes(32) || codes.includes(613)) {
    hint = 'Rate limited (code 4/17/32/613) — every retry was exhausted. Wait and retry; this is not a permission problem.';
  } else if (codes.includes(100) || codes.includes(803)) {
    hint = 'Campaign ID does not exist for these tokens (code 100/803). Either the ID is wrong, or the campaign lives in an ad account / Business Manager that none of these tokens can see. Verify the ID in Ads Manager and confirm the token user is assigned to that specific ad account (BM asset access is per-account, not per-business).';
  } else {
    hint = 'See probeFailures for the raw Graph API errors.';
  }

  return [{
    json: {
      ok: false,
      error: `No token could read campaign ${campaignId}`,
      hint,
      campaignId,
      tokensTried: tokens.length,
      probeFailures,
      tokenLiveness: liveness,
    },
  }];
}

try {
  const data = await getFullCampaign(campaignId, workingToken);
  if (data.error) {
    return [{ json: { ok: false, error: data.error, tokenIndex: workingIndex } }];
  }
  // Drop adsets with zero active ads (rare — happens if every ad in an
  // otherwise-active adset is paused) and recompute totalAds. ACTIVE filtering
  // is done at the Graph API call, so this is just a tidy-up pass.
  if (Array.isArray(data.adsets)) {
    const kept = data.adsets.filter((a) => Array.isArray(a.ads) && a.ads.length > 0);
    data.adsets = kept;
    data.totalAds = kept.reduce((sum, a) => sum + a.ads.length, 0);
  }
  return [{ json: { ok: true, data, tokenIndex: workingIndex } }];
} catch (e) {
  return [{ json: { ok: false, error: e.message || String(e), tokenIndex: workingIndex } }];
}
